1	# Serve the built SPA AND reverse-proxy the API + MCP to the backend.
2	
3	# The client-facing scheme, forwarded upstream (#1138). Prefer the edge's
4	# X-Forwarded-Proto (this hop never terminates TLS, so $scheme is always `http`
5	# and would strip cookie-`Secure` on live HTTPS — ADR 0032); fall back to
6	# $scheme only on a direct connection (compose / docker run).
7	
8	# The origin-secret guard's static "<secret>:<secret>" map key is 81 bytes with the
9	# 40-char terraform secret — over the 64-byte default bucket size, which ABORTS nginx
10	# at startup (#1380). MUST precede the first `map`: a later placement is rejected as
11	# "duplicate" (parsing a map freezes the hash sizes).
12	map_hash_bucket_size 128;
13	map $http_x_forwarded_proto $dataq_forwarded_proto {
14	    default $http_x_forwarded_proto;
15	    ""      $scheme;
16	}
17	
18	# ── Content-Security-Policy (#1387) ───────────────────────────────────────────
19	# Assembled here (not in nginx-security-headers.conf) because `connect-src` is a
20	# per-deployment runtime fact: the SPA's OIDC client hits discovery/JWKS/token
21	# endpoints directly. DATAQ_CSP_CONNECT_SRC is deliberately NOT derivable from
22	# DATAQ_AUTH_AUTHORITY (an authority carries a path, CSP matches by path prefix,
23	# and Azure AD's token endpoint — and Cognito's separate auth host — sit outside
24	# it). Its Dockerfile default is `https:`, not empty, so a BYO image upgrade
25	# can't silently break sign-in. An empty $dataq_csp turns the header off (nginx
26	# omits empty add_header values) — a supported no-rebuild off switch.
27	map $host $dataq_csp {
28	    default "default-src 'self'; base-uri 'self'; object-src 'none'; frame-ancestors 'none'; form-action 'self'; img-src 'self' data: blob:; font-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self'; worker-src 'self' blob:; connect-src 'self' ${DATAQ_CSP_CONNECT_SRC}";
29	}
30	
31	# ── Origin-secret guard (#1355) ───────────────────────────────────────────────
32	# When DATAQ_ORIGIN_SECRET is set, every request must carry the matching
33	# X-DataQ-Origin-Secret header or be 403'd. Two-level map encoding: with the
34	# secret EMPTY the key starts with ":" so `~^:` opens the guard (guard off);
35	# nginx's exact match beats the regex when the secret matches. The ":" delimiter
36	# is safe only because the terraform secret is `special = false` alphanumeric —
37	# a hand-provisioned secret containing ":" breaks the map.
38	map "${DATAQ_ORIGIN_SECRET}:$http_x_dataq_origin_secret" $dataq_origin_bad {
39	    default 1;
40	    "~^:"   0;
41	    "${DATAQ_ORIGIN_SECRET}:${DATAQ_ORIGIN_SECRET}" 0;
42	}
43	
44	# Second level: exempt the load balancer's OWN health check.
45	map "$dataq_origin_bad:$uri" $dataq_origin_reject {
46	    default 0;
47	    "~^1:"  1;
48	    "1:/_alb-health" 0;
49	}
50	
51	server {
52	    listen 8080;
53	    server_name _;
54	    root /usr/share/nginx/html;
55	    index index.html;
56	
57	    # Don't advertise the exact nginx build in every response / error page.
58	    server_tokens off;
59	
60	    # Security headers (#1387).
61	    include /etc/nginx/nginx-security-headers.conf;
62	
63	    # Origin-secret guard (#1355, maps above).
64	    if ($dataq_origin_reject) {
65	        return 403;
66	    }
