87	    # REST API — same-origin /api/* forwarded to the backend. proxy_pass uses a variable, so the
88	    # original URI isn't auto-appended.
89	    location /api/ {
90	        set $dataq_upstream "${DATAQ_API_UPSTREAM}";
91	        proxy_pass $dataq_upstream$request_uri;
92	        proxy_http_version 1.1;
93	        proxy_set_header Connection "";
94	        proxy_ssl_server_name on;
