98	        # Verified above, stripped here (#1355 review): the origin secret must not ride into the
99	        # backend request context.
100	        proxy_set_header X-DataQ-Origin-Secret "";
101	    }
102	
103	    # Liveness probe — the api's top-level /healthz (NOT under /api), proxied so it stays
104	    # reachable now that the api has no public ingress (ADR 0028 §5). Exact match so it
105	    # can't shadow an SPA route; HTTP/1.1 is mandatory — ACA ingress 426s HTTP/1.0 (#511).
106	    location = /healthz {
107	        set $dataq_upstream "${DATAQ_API_UPSTREAM}";
108	        proxy_pass $dataq_upstream$request_uri;
109	        proxy_http_version 1.1;
