130	        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
131	        proxy_set_header X-Forwarded-Proto $dataq_forwarded_proto;
132	        # Verified above, stripped here (#1355 review): the origin secret must not ride into the
