137	    # Long-cache the fingerprinted build output; never cache index.html (it points at the current
138	    # asset hashes).
139	    location ~* ^/assets/.+\.(?:js|mjs|css|map|png|jpe?g|gif|svg|ico|webp|avif|woff2?|ttf|eot)$ {
